                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTCurrentIdentities.b_car"),
                H("The original antighost CAR on the tensor carrier"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every D : LatticeData, integers m,n and x : State D, B_m(B_n x) + B_n(B_m x) = 0, where B_j = ghostB D j. The proof lifts the existing bc-ghost CAR by the original tensor map and evaluates it at x. No matrix, inverse Gram, rank, cycle, parity or energy hypothesis is needed."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("latticebrstcurrentidentities-b-square"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTCurrentIdentities.b_square"),
                H("The literal same-mode antighost square vanishes"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every D, integer m and original state x, B_m(B_m x) = 0. The same-mode CAR gives twice this vector equal to zero; the nonzero scalar 2 in Complex cancels. This is a consumed consequence of b_car, used in the current closure and current Leibniz proofs."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("latticebrstcurrentidentities-current-b0"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTCurrentIdentities.current_b0"),
                H("Relative antighost closure of the actual current"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For every D and x,y : State D satisfying B_0 x = 0 and B_0 y = 0, B_0 K(x,y) = 0. CAR moves B_0 across B_(-1), and the actual beta-mode-one Borcherds identity eliminates the remaining B_(-1) square. Neither input is assumed to be a Q-cycle; no rank or positivity restriction is added."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("latticebrstcurrentidentities-current-l0"),
                DeclarationHandle.Create("D5/S3/VertexAlgebra/Lattice/PhysicalLie/LatticeBRSTCurrentIdentities.current_L0"),
                H("Energy covariance from the actual Ward identity"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("For D : LatticeData, H : Matrix (Fin D.rank) (Fin D.rank) Complex, hHG : H * gramComplex D = 1 and hGH : gramComplex D * H = 1, and arbitrary x,y : State D, totalL0 D H (K(x,y)) = K(totalL0 D H x,y) + K(x,totalL0 D H y). The proof combines the original identity {Q,B_0} = totalL0 with the two odd current derivation laws. There is no critical-rank assumption and neither x nor y must be closed, homogeneous or of zero energy."))), DescribeRole.Theorem),
